"""

    :param sent:
    :param word2id:
    :return:
    """
def sentence2id(sent: Any, word2id: Any) -> object {
    sentence_id = [];
    for word in sent {
        if word.isdigit() {
            word = '<NUM>';
        }
        if (word not in word2id) {
            word = '<UNK>';
        }
        sentence_id.append(word2id[word]);
    }
    return sentence_id;
}

test_blocks:
test "t0" {
    assert (
        sentence2id(
            ['<UNK>', 'a', 'boy', 'playing', 'guitar', '<UNK>'],
            {'<UNK>': 1, '<NUM>': 2, 'a': 3, 'boy': 4, 'playing': 5, 'guitar': 6}
        )
        == [1, 3, 4, 5, 6, 1]
    );;
}

